// useVoiceCapture hook outline (RN side)
function useVoiceCapture(onFrame) {
  useEffect(() => {
    NativeVoiceModule.startCapture({ sampleRate: 16000, channels: 1 });
    const sub = NativeVoiceModule.onFrame(({ frame, ts }) => onFrame(frame, ts));
    return () => { sub.remove(); NativeVoiceModule.stopCapture(); };
  }, [onFrame]);
}
```

